def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    rich_threats = 0
    weak_or_broke = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 100:
                rich_threats += 1
            if opp.get('budget', 0) <= 5 or opp.get('hp', 10) <= 2:
                weak_or_broke += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive_opponents:
        return float(min(budget, 10))

    highest_prev = max(prev_bids) if prev_bids else 0
    low_prev = min(prev_bids) if prev_bids else 0

    severe_need = hp <= 2 or no_water >= 2
    urgent_need = hp <= 4 or no_water >= 1

    base = 0.0

    if severe_need:
        if rich_threats >= 1:
            base = 126.0
        else:
            base = max(62.0, highest_prev + 3.0)
    elif urgent_need:
        if highest_prev >= 115:
            base = 118.0
        elif highest_prev >= 70:
            base = highest_prev + 2.0
        else:
            base = 58.0
    else:
        if rich_threats >= 2:
            base = 6.0
        elif highest_prev >= 115:
            base = 8.0
        elif highest_prev >= 70:
            base = 18.0
        else:
            base = max(14.0, low_prev + 1.0 if prev_bids else 14.0)

    if weak_or_broke >= 2 and not severe_need and highest_prev < 115:
        base = max(base, 22.0)

    if supply <= 16 and urgent_need:
        base += 4.0
    elif supply >= 24 and not urgent_need:
        base -= 2.0

    if hp >= 8 and no_water == 0 and rich_threats >= 1:
        base = min(base, 12.0)

    bid = min(float(budget), float(max(0.0, base)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Calculate estimated fair price based on competition
    num_agents = len(alive_opponents) + 1
    fair_price = (supply / num_agents) * 1.1

    # Aggressive bidding if HP is low
    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # Observe yesterday's aggression
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        # If others are spending heavily, match to survive, otherwise play conservatively
        if max_prev > DAILY_SALARY * 0.6:
            return min(my_status['budget'], max(fair_price, max_prev * 1.05))

    return min(my_status['budget'], max(fair_price, 25.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.45)

    yesterday_bids = []
    eric_prev_bid = 0.0
    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev['bid'])
                if opp_id == 'Eric':
                    eric_prev_bid = prev['bid']

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else (DAILY_SALARY * 0.5)

    bid = DAILY_SALARY * 0.55

    if highest_prev_bid > (DAILY_SALARY * 0.4):
        bid = max(bid, highest_prev_bid + 1.5)

    if eric_prev_bid > (DAILY_SALARY * 0.7):
        bid = max(bid, eric_prev_bid + 2.0)

    if my_status['hp'] <= 2:
        bid = max(bid, DAILY_SALARY * 0.95, highest_prev_bid + 5.0)
    elif my_status['hp'] <= 4:
        bid = max(bid, DAILY_SALARY * 0.8, highest_prev_bid + 3.0)

    num_agents_competing = len(alive_opponents) + 1
    total_demand_water = WATER_REQ * num_agents_competing

    if day_context['supply'] < total_demand_water * 0.8:
        bid *= 1.15
    elif day_context['supply'] > total_demand_water * 1.5:
        bid *= 0.9

    final_bid = min(my_status['budget'], bid)
    final_bid = max(final_bid, WATER_REQ * 0.5)

    return final_bid
